 const levels=[[{x:280,y:60,t:'Сұрақ',n:'root'}],[{x:145,y:165,t:'x₁ ≤ 0.48',n:'node'},{x:415,y:165,t:'x₂ ≤ 0.62',n:'node'}],[{x:72,y:270,t:'A',n:'leaf'},{x:212,y:270,t:'B',n:'leaf'},{x:348,y:270,t:'A',n:'leaf'},{x:488,y:270,t:'B',n:'leaf'}]];
