function treeSVG(t,small=false,highlight=[]){const width=560,height=390,maxDepth=node=>node.left?1+Math.max(maxDepth(node.left),maxDepth(node.right)):0,dep=maxDepth(t);let edges='',nodes='';
 const draw=(n,x,y,spread,d)=>{const active=highlight.includes(n),leaf=!n.left,r=small?5:dep>2?13:20;if(n.left){const yy=y+(small?32:Math.min(95,275/Math.max(1,dep)));
 [[n.left,-1],[n.right,1]].forEach(([ch,side])=>{const xx=x+side*spread,isPath=highlight.includes(ch);edges+=`<path class="branch" d="M${x} ${y+r} C${x} ${y+45},${xx} ${yy-45},${xx} ${yy-r}" stroke="${isPath?'var(--accent)':'var(--green)'}" opacity="${highlight.length&&!isPath?.22:.65}" stroke-width="${isPath?2.5:1.1}" fill="none"/>`;draw(ch,xx,yy,spread/2,d+1)})}
 const label=leaf?(n.value?'A':'B'):`x${n.f+1} ≤ ${n.threshold.toFixed(2)}`;
 nodes+=`<g class="node node-in" tabindex="0" role="button" aria-label="${leaf?'Жапырақ':'Шарт'}: ${label}; ${n.n} мысал; Gini ${n.impurity.toFixed(3)}" data-node-info="${n.n} мысал · ${leaf?'Класс '+label:label} · Gini ${n.impurity.toFixed(3)}"><circle cx="${x}" cy="${y}" r="${r}" fill="${active?'var(--accent)':leaf?(n.value?'#49e6a12b':'#ffa9782b'):'var(--panel)'}" stroke="${active?'var(--accent)':leaf?(n.value?'#49e6a1':'#ffa978'):'var(--green)'}"/><text x="${x}" y="${y+3}" text-anchor="middle" font-family="monospace" font-size="${leaf?10:dep>2?6:8}" fill="${active?'var(--bg)':'var(--ink)'}">${label}</text>${!small?`<text x="${x}" y="${y+r+14}" fill="var(--muted)" font-size="7" text-anchor="middle">n = ${n.n}</text>`:''}</g>`};draw(t,280,45,130,0);
 return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Оқытылған шешім ағашы">${edges}${nodes}<text x="280" y="375" text-anchor="middle" font-size="9" fill="var(--muted)">${dep===0?'АЛҒАШҚЫ ТҮЙІН · АҒАШТЫ ӨСІРІП КӨР':'ШАРТ → БӨЛУ → БОЛЖАМ'}</text></svg>`}
function bindNodes(){let tip;$$('[data-node-info]').forEach(n=>{const show=()=>{tip?.remove();tip=document.createElement('div');tip.className='tooltip';tip.textContent=n.dataset.nodeInfo;$('#scene').append(tip)};n.onpointerenter=show;n.onfocus=show;n.onclick=show;n.onpointerleave=()=>tip?.remove();n.onblur=()=>tip?.remove()})}
function dataSVG(fn,boundary=true){const w=560,h=390,left=50,top=25,cw=465,ch=310;let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Екі класс және модельдің шешім аймақтары"><rect x="${left}" y="${top}" width="${cw}" height="${ch}" fill="var(--bg)"/>`;
 if(boundary)for(let ix=0;ix<28;ix++)for(let iy=0;iy<20;iy++){const v=fn([(ix+.5)/28,(iy+.5)/20]);s+=`<rect x="${left+ix*cw/28}" y="${top+(19-iy)*ch/20}" width="${cw/28+.5}" height="${ch/20+.5}" fill="${v?'#49e6a1':'#ffa978'}" opacity=".12"/>`}
 for(let i=0;i<=4;i++){const x=left+i*cw/4,y=top+i*ch/4;s+=`<path d="M${x} ${top}v${ch}M${left} ${y}h${cw}" stroke="var(--line)" stroke-width=".5"/><text x="${x}" y="${top+ch+20}" text-anchor="middle" fill="var(--muted)" font-size="8">${(i/4).toFixed(2)}</text>`}
 const pt=(r,isTest)=>{const x=left+r.x[0]*cw,y=top+(1-r.x[1])*ch,c=r.y?'#49e6a1':'#ffa978';return isTest?`<path d="M${x} ${y-3}l3 3-3 3-3-3z" fill="none" stroke="${c}"/>`:`<circle cx="${x}" cy="${y}" r="3.5" fill="${c}" stroke="var(--bg)" stroke-width="1"/>`};s+=test.map(r=>pt(r,true)).join('')+rows.map(r=>pt(r,false)).join('');const px=left+state.px*cw,py=top+(1-state.py)*ch;s+=`<circle cx="${px}" cy="${py}" r="9" fill="none" stroke="var(--ink)" stroke-width="1.5"/><path d="M${px-13} ${py}h26M${px} ${py-13}v26" stroke="var(--ink)" stroke-width=".6"/><text x="280" y="375" text-anchor="middle" font-size="9" fill="var(--muted)">x₁ · ГРАФИККЕ БАСЫП, НҮКТЕ ҚОС</text><text x="18" y="180" fill="var(--muted)" font-size="10">x₂</text><rect id="plot-hit" x="${left}" y="${top}" width="${cw}" height="${ch}" fill="transparent" style="cursor:crosshair"/></svg>`;return s}
function bindPlot(fn){const hit=$('#plot-hit');if(!hit)return;hit.onclick=e=>{if(rows.length>=70){$('#scene-status').textContent='70 нүкте шегі. Жаңадан бастау үшін «Тазарту» батырмасын бас.';return}const svg=hit.ownerSVGElement,p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(svg.getScreenCTM().inverse()),row={x:[Math.max(0,Math.min(1,(q.x-50)/465)),Math.max(0,Math.min(1,1-(q.y-25)/310))],y:pointClass,id:rows.length+1};rows.push(row);state.extra=rows.slice(40);save();fn()}}
function classButtons(){return `<div class="segmented" aria-label="Жаңа нүктенің класы"><button data-class="1" class="selected">● A класы</button><button data-class="0">● B класы</button></div><button id="add-point" class="btn secondary small">Осы нүктені дерекке қосу +</button>`}
