function initTree(){view='tree';$('#controls').innerHTML=`<div class="segmented"><button data-view="tree" class="selected">Ағаш</button><button data-view="data">Деректер</button></div>${range('depth','Ағаш тереңдігі',0,4,state.depth)}<div class="lab-actions"><button id="grow" class="btn small">Ағашты өсіру +</button><button id="clear" class="btn secondary small">Тазарту ↻</button></div>${pointControls()}${classButtons()}<div id="metrics"></div><p class="hint">A — жасыл · B — сарғыш. Түйінді таңда: шарт пен мысал санын көр.</p>`;
 bindRange('depth',updateTree);bindPoint(updateTree);bindClass();$('#grow').onclick=()=>{state.depth=Math.min(4,state.depth+1);$('#depth').value=state.depth;save();updateTree()};$('#clear').onclick=()=>resetData(updateTree);$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));updateTree()});
 let weatherStep=0;$$('[data-weather]').forEach(b=>b.onclick=()=>{const yes=+b.dataset.weather;if(weatherStep===2){weatherStep=0;$('#weather-q').textContent='Жаңбыр жауып тұр ма?';$('#weather-result').textContent='Қайта басталды.';return}if(yes){$('#weather-result').textContent='Үйде қаламыз. Жауапқа дейінгі жол аяқталды.';weatherStep=2;$('#weather-q').textContent='Нәтиже: серуенге шықпаймыз.'}else if(weatherStep===0){weatherStep=1;$('#weather-q').textContent='Жел қатты ма?';$('#weather-result').textContent='Жаңбыр жоқ → келесі шарт.'}else{$('#weather-result').textContent='Серуенге шығамыз! Жаңбыр да, қатты жел де жоқ.';weatherStep=2;$('#weather-q').textContent='Нәтиже: серуенге шығамыз.'}if(weatherStep===2)$('#weather-result').textContent+=' Қайта бастау үшін кез келген жауапты бас.'});
 const updateGini=()=>{const a=+$('#g-a').value,b=+$('#g-b').value,n=a+b,p=n?a/n:0,q=n?b/n:0;$('#g-a-out').textContent=a;$('#g-b-out').textContent=b;$('#gini-balls').innerHTML='<i></i>'.repeat(a)+'<i class="other"></i>'.repeat(b);$('#gini-value').textContent=n?(1-p*p-q*q).toFixed(3):'—';$('#gini-explain').textContent=n?`Жасыл үлесі: ${p.toFixed(2)}, сарғыш үлесі: ${q.toFixed(2)}. Gini = 1 − ${p.toFixed(2)}² − ${q.toFixed(2)}².`:'Ыдыс бос. Gini есептеу үшін кемінде бір шар қос.'};$('#g-a').oninput=updateGini;$('#g-b').oninput=updateGini;updateGini();updateTree();}
function updateTree(){tree=fit(rows,state.depth);const fn=x=>predict(tree,x),path=pathOf(tree,[state.px,state.py]);setOutput('depth',state.depth);setOutput('px',state.px.toFixed(2));setOutput('py',state.py.toFixed(2));$('#grow').disabled=state.depth>=4;$('#scene').innerHTML=view==='tree'?treeSVG(tree,false,path):dataSVG(fn);$('#scene-status').textContent=`${path.length-1} шарт тексерілді · ${path.at(-1).n} мысал бар жапырақ · ${fn([state.px,state.py])?'A':'B'} класы`;$('#metrics').innerHTML=accuracyHTML(accuracy(fn,rows),accuracy(fn,test));$('#prediction').textContent=fn([state.px,state.py])?'A ↗':'B ↘';bindNodes();bindPlot(updateTree)}
function initForest(){view='forest';$('#controls').innerHTML=`<div class="segmented"><button data-fview="forest" class="selected">Орман</button><button data-fview="single">Бір ағаш</button><button data-fview="data">Деректер</button></div>${range('count','Ағаш саны',1,21,state.count,2)}${pointControls()}<div class="lab-actions"><button id="retrain" class="btn small">Қайта оқыту ↻</button><button id="clear" class="btn secondary small">Тазарту</button></div>${classButtons()}<div id="metrics"></div><p id="votes" class="hint"></p>`;
 bindRange('count',updateForest);bindPoint(updateForest);bindClass();$('#retrain').onclick=()=>{state.seed++;save();updateForest()};$('#clear').onclick=()=>resetData(updateForest);$$('[data-fview]').forEach(b=>b.onclick=()=>{view=b.dataset.fview;$$('[data-fview]').forEach(x=>x.classList.toggle('selected',x===b));updateForest()});$('#resample').onclick=()=>{state.seed++;save();sample();updateForest()};sample();updateForest()}
function sample(){const r=rng(state.seed),ids=Array.from({length:20},()=>1+Math.floor(r()*20)),counts=ids.reduce((a,v)=>(a[v]=(a[v]||0)+1,a),{});$('#bootstrap').innerHTML=ids.map(i=>`<span class="${counts[i]>1?'dup':''}">${i}</span>`).join('');$('#bootstrap-note').textContent=`20 таңдауда ${Object.keys(counts).length} бірегей объект. ${20-Object.keys(counts).length} объект таңдамаға кірмеді.`}
function updateForest(){trees=forest(rows,state.count,state.seed);tree=fit(rows,4);setOutput('count',state.count);setOutput('px',state.px.toFixed(2));setOutput('py',state.py.toFixed(2));const x=[state.px,state.py],votes=trees.map(t=>predict(t.tree,x)),a=votes.filter(Boolean).length,fn=view==='single'?p=>predict(tree,p):p=>forestPredict(trees,p);
 if(view==='forest'){const small=matchMedia('(max-width:720px)').matches,w=small?560:960,h=small?470:300,cols=Math.min(state.count,small?3:state.count>12?7:5),gap=(w-120)/cols,rowGap=small?50:70,barY=small?415:254,barWidth=w-160;
 let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${state.count} ағаштың тәуелсіз дауыстары">`;
 trees.forEach((t,i)=>{const xx=60+gap/2+(i%cols)*gap,yy=25+Math.floor(i/cols)*rowGap,c=votes[i]?'#49e6a1':'#ffa978';s+=`<g class="node node-in" data-tree="${i}" tabindex="0" role="button" aria-label="${i+1}-ағаш, ${votes[i]?'A':'B'} класы" style="color:${c};animation-delay:${i*.025}s"><g transform="translate(${xx},${yy}) scale(${small?.8:1.2})">${iconTree}</g><text x="${xx}" y="${yy+(small?43:58)}" text-anchor="middle" font-size="${small?14:11}" fill="${c}">T${i+1} · ${votes[i]?'A':'B'}</text></g>`});
 s+=`<path d="M80 ${barY-12}H${w-80}" stroke="var(--line)"/><rect x="80" y="${barY}" width="${barWidth*a/state.count}" height="9" fill="#49e6a1" rx="3"/><rect x="${80+barWidth*a/state.count}" y="${barY}" width="${barWidth*(1-a/state.count)}" height="9" fill="#ffa978" rx="3"/><text x="80" y="${barY+32}" fill="#49e6a1" font-size="13">A: ${a} дауыс</text><text x="${w-80}" y="${barY+32}" text-anchor="end" fill="#ffa978" font-size="13">B: ${state.count-a} дауыс</text></svg>`;$('#scene').innerHTML=s;$$('[data-tree]').forEach(el=>{const show=()=>{selected=+el.dataset.tree;const t=trees[selected];$('#scene-status').textContent=`T${selected+1}: ${new Set(t.indices).size} бірегей мысал · дауыс ${votes[selected]?'A':'B'} · әр бөлуде кездейсоқ белгі`};el.onclick=show;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}})
 }else $('#scene').innerHTML=dataSVG(fn,true);
 $('#metrics').innerHTML=accuracyHTML(accuracy(fn,rows),accuracy(fn,test));$('#prediction').textContent=fn(x)?'A ↗':'B ↘';$('#votes').textContent=`Орман дауыстары: A ${a}/${state.count} · B ${state.count-a}/${state.count}. ${view==='single'?'Дәлдік жалғыз ағаш үшін көрсетілген.':'Дәлдік орман үшін көрсетілген.'}`;$('#scene-status').textContent=`${state.count} тәуелсіз модель · тереңдігі ≤ 4 · bootstrap + кездейсоқ белгі`;bindPlot(updateForest)}
const trainR=regressionData(),validR=regressionData(29,99);
function initBoost(){$('#controls').innerHTML=`${range('rate','Learning rate · η',.01,1,state.rate,.01)}${range('steps','Итерация / ағаш саны',0,40,state.steps)}<div class="lab-actions"><button class="btn small" id="add-tree">Келесі ағаш +</button><button class="btn secondary small" id="boost-reset">Басынан ↻</button></div><div class="stats"><div class="stat">TRAIN MSE<b id="train-mse"></b></div><div class="stat">VALIDATION<b id="valid-mse"></b></div><div class="stat">АҒАШ<b id="step-count"></b></div></div><div id="loss-chart"></div><div class="legend"><span>Train loss</span><span class="orange">Validation loss</span></div><p class="hint">Ақ нүкте — шын мән. Сарғыш кесінді — қалдық. Күлгін сызық — ортақ болжам.</p>`;bindRange('rate',updateBoost);bindRange('steps',updateBoost);$('#add-tree').onclick=()=>{state.steps=Math.min(40,state.steps+1);$('#steps').value=state.steps;save();updateBoost()};$('#boost-reset').onclick=()=>{state.steps=0;$('#steps').value=0;save();updateBoost()};updateBoost()}
function updateBoost(){boostModel=boosting(trainR,validR,state.steps,state.rate);const m=boostModel;setOutput('rate',state.rate.toFixed(2));setOutput('steps',state.steps);$('#add-tree').disabled=state.steps>=40;$('#train-mse').textContent=m.history.at(-1).train.toFixed(3);$('#valid-mse').textContent=m.history.at(-1).validation.toFixed(3);$('#step-count').textContent=state.steps;
 const small=matchMedia('(max-width:720px)').matches,w=small?560:1000,chartHeight=small?390:300,left=small?50:70,right=small?515:930,base=small?330:250,scale=small?53:37;
 const xp=x=>left+x*(right-left),yp=y=>base-y*scale;let s=`<svg viewBox="0 0 ${w} ${chartHeight}" role="img" aria-label="Болжам сызығы, шын мәндер және қалдықтар">`;
 for(let i=0;i<=6;i++)s+=`<path d="M${left} ${yp(i)}H${right}" stroke="var(--line)" stroke-width=".6"/><text x="${left-18}" y="${yp(i)+3}" fill="var(--muted)" font-size="8">${i}</text>`;
 trainR.forEach(r=>s+=`<path d="M${xp(r.x[0])} ${yp(r.y)}V${yp(m.predict(r.x))}" stroke="#ffa978" opacity=".7" stroke-width="1"/><circle cx="${xp(r.x[0])}" cy="${yp(r.y)}" r="3.5" fill="#f4f0f8"/>`);
 const pts=Array.from({length:201},(_,i)=>[xp(i/200),yp(m.predict([i/200]))]);s+=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" stroke="var(--accent)" stroke-width="2.5" fill="none"/><path d="M${left} ${base+5}H${right}M${left} 20V${base+5}" stroke="var(--muted)" stroke-width=".5"/><text x="${w/2}" y="${chartHeight-15}" text-anchor="middle" font-size="9" fill="var(--muted)">x · ${state.steps===0?'АЛҒАШҚЫ БОЛЖАМ — ОРТАША МӘН':state.steps+' АҒАШТЫҢ ЖИНАҚТАЛҒАН БОЛЖАМЫ'}</text><text x="20" y="30" fill="var(--muted)" font-size="9">y</text></svg>`;$('#scene').innerHTML=s;
 const all=boosting(trainR,validR,40,state.rate).history,max=Math.max(...all.flatMap(x=>[x.train,x.validation]))*1.1;let chart=`<svg class="tiny-chart" viewBox="0 0 420 80" role="img" aria-label="Оқыту және validation қатесінің өзгеруі">`;
 for(const [key,color]of[['train','var(--accent)'],['validation','#ffa978']])chart+=`<polyline points="${m.history.map((v,i)=>`${8+i/40*400},${65-v[key]/max*56}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.6"/>`;
 chart+=`<path d="M8 67H410" stroke="var(--line)"/><text x="8" y="79" fill="var(--muted)" font-size="7">0</text><text x="400" y="79" fill="var(--muted)" font-size="7">40</text></svg>`;$('#loss-chart').innerHTML=chart;$('#scene-status').textContent=`${trainR.length} оқыту / ${validR.length} validation нүктесі · η = ${state.rate.toFixed(2)} · CART тереңдігі 2`;
 const i=8,x=trainR[i].x,old=boosting(trainR,validR,Math.max(0,state.steps-1),state.rate).predict(x),h=state.steps?predict(m.trees.at(-1),x):0;$('#boost-example').innerHTML=state.steps?`<b>Нақты мысал, x = ${x[0].toFixed(2)}:</b><br>Алдыңғы болжам ${old.toFixed(3)} + ${state.rate.toFixed(2)} × түзету ${h.toFixed(3)} = <b>${m.predict(x).toFixed(3)}</b>.<br>Шын мән: ${trainR[i].y.toFixed(3)}. Жаңа қалдық: ${(trainR[i].y-m.predict(x)).toFixed(3)}.`:`Алғашқы болжам — орташа мән: <b>${m.base.toFixed(3)}</b>. Жаңа ағаш қосып, есептің өзгеруін көр.`;
}
